INSERT INTO feature VALUES('instrument-seam','editor','The engine records its own work through one sink','language-server','implemented','ordinary',NULL,'The session''s judgement and admission take an `Instrument` sink as a type parameter and tell it each phase entered and left, the forms molded, the items judged and the declarations crossed. The silent sink is zero-sized, and the compiler removes each call on it. The `Counts` sink answers a dense column that the session counts each declaration''s work into, and asks the admission to record the census of each declaration that crosses with no clock read; the account takes the column into its rows. The `Timings` sink reads the clock, and the thread''s allocation count when the process installs the counting allocator, at each phase boundary and between the items that the incremental pass judges; the admission meters each declaration that crosses, and the account keeps the samples in rings of 32. At the timings layer the recheck''s timing line reads its walls from the samples. The `Trace` sink lends each incremental pass a buffer that the checker''s machine writes its steps into, and folds each judged item''s steps into the item''s tree. The hub runs each job of a recheck at the sink its client''s subscription chooses, one branch for each job, and only a build with the `instrument` feature compiles a recording sink.','surface-session surface-lsp surface-dispatcher surface-driver core-checker','crates/surface-session/tests/instrument.rs crates/surface-session/tests/counts.rs crates/surface-session/tests/timings.rs crates/surface-session/tests/trace.rs crates/core-checker-bridge/src/bridge/tests.rs crates/surface-driver/src/allocator.rs','crate-tests',NULL);
